// The city's texts (city.js) in Polish, as the sentences take them: server in the genitive ("Serwer miasta Brno nie
// odpowiada"), dataName in the nominative ("… obecnie nie odpowiada"), dataShort in the genitive ("według danych miasta
// Brno i OSM"), techMap in the genitive ("Wczytywanie mapy technicznej IPR…"). Czech town names stay undeclined after
// "miasta", as Polish official texts do with foreign names; the Polish exonyms (Pilzno, Ostrawa, Igława…) are not used,
// the map and the search show the Czech names.
// The map in the genitive for "Wczytywanie {map}…".
const gen = (map) => map.replace(/^Mapa techniczna/, "mapy technicznej").replace(/^Mapa tematyczna/, "mapy tematycznej").replace(/^Ewidencja/, "ewidencji");
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: map, dataShort: `${data} i OSM`, techMap: gen(map),
  parkingSource: parking, rulesHead: `Szerokości według praskiego Podręcznika IPR (C.2), dla miasta ${name} orientacyjnie:`, credit,
});
const NATIONAL = "Mapa techniczna ČÚZK";
const NATIONAL_GEN = "mapy technicznej ČÚZK";
const TECH_PARKING = "parkingi z mapy technicznej";
const RUIAN = "RÚIAN © ČÚZK, 2026 (CC BY 4.0, zmodyfikowane)";
